    let output = input.replace(/rgba\(#(.*?),/g, (match, hex) => {
      let rgb = hexRgb(hex),
          matchHex = new RegExp('#' + hex);

      // If conversion fails, emit a warning
      if (!rgb) {
        result.warn('not a valid hex', { node: decl });
        return match;
      }

      rgb = rgb.toString();

