      if (type === 'Array') {
        value = value.split(',')
      } else if (type === 'RegExp') {
        try {
          value = new RegExp(value)
        } catch (e) {
          return cli.error('The "' + name + '" option received an invalid expression: "' + value + '".')
        }
      } else if (type === 'Number') {
        var number = value * 1
        if (isNaN(number)) {
          return cli.error('The "' + name + '" option received a non-numerical argument: "' + value + '".')
        }
      }
      args[name] = value
    } else {
