original_string:
function partition(a, l, h, c) {
  const p = a[pivot(a, l, h, c)];

  let i = l - 1;
  let j = h + 1;

  for (;;) {
    do {
      i++;
    } while (c(a[i], p) < 0);

    do {
      j--;
    } while (c(a[j], p) > 0);

    if (i < j) {
      [a[i], a[j]] = [a[j], a[i]];
    } else {
      return j;
    }
  }
}

